import { readFileSync } from "node:fs";
import { hashTypedData, recoverTypedDataAddress, type Hex } from "viem";
import { describe, expect, it } from "vitest";
import { ACK_CHAIN_IDS, ackTypedData } from "./ack";

// Vectors generated by viem for the Rust verifier (blueprint 2.7, K14). The page must build
// the exact same typed data, or the wallet signs something the contract rejects.
const vectors = JSON.parse(
  readFileSync(new URL("../../../../fixtures/vectors/ack-v1.json", import.meta.url), "utf8"),
) as {
  ack: {
    name: string;
    chain_id: number;
    root_contract: string;
    token_id: string;
    terms_hash: Hex;
    amount_due: string;
    due_date: number;
    digest: Hex;
    signer: Hex;
    signature: Hex;
  }[];
  tamper_ack: (typeof vectors.ack)[number][];
};

const input = (v: (typeof vectors.ack)[number]) => ({
  chainId: v.chain_id,
  rootContract: v.root_contract,
  tokenId: v.token_id,
  termsHash: v.terms_hash,
  amountDue: BigInt(v.amount_due),
  dueDate: BigInt(v.due_date),
});

describe("ackTypedData", () => {
  it.each(vectors.ack.map((v) => [v.name, v] as const))(
    "%s: digest matches the vector",
    (_n, v) => {
      expect(hashTypedData(ackTypedData(input(v)))).toBe(v.digest);
    },
  );

  it.each(vectors.ack.map((v) => [v.name, v] as const))(
    "%s: signature recovers the signer",
    async (_n, v) => {
      const recovered = await recoverTypedDataAddress({
        ...ackTypedData(input(v)),
        signature: v.signature,
      });
      expect(recovered).toBe(v.signer);
    },
  );

  it("a tampered message never recovers the signer of the original", async () => {
    for (const t of vectors.tamper_ack) {
      const base = vectors.ack[0]!;
      const recovered = await recoverTypedDataAddress({
        ...ackTypedData(input(t)),
        signature: base.signature,
      });
      expect(recovered).not.toBe(base.signer);
    }
  });

  it("uses the fixed domain with the zero verifying contract and kind OPENRAIL_ACK_V1", () => {
    const td = ackTypedData(input(vectors.ack[0]!));
    expect(td.domain).toEqual({
      name: "Openrail",
      version: "1",
      chainId: 1,
      verifyingContract: "0x0000000000000000000000000000000000000000",
    });
    expect(td.primaryType).toBe("Acknowledge");
    expect(td.message.kind).toBe("OPENRAIL_ACK_V1");
  });
});

describe("ACK_CHAIN_IDS", () => {
  it("are the six EVM pay-link chains", () => {
    expect([...ACK_CHAIN_IDS].sort((a, b) => a - b)).toEqual([1, 10, 56, 137, 8453, 42161]);
  });
});
